// executeReadOnlyQuery runs a SELECT with a timeout and row cap. The SQL has already
// been validated as a single read-only statement. For PostgreSQL it runs inside a
// READ ONLY transaction with a per-statement timeout and optional work_mem cap
// (sandbox), so a heavy or accidentally-mutating query can't harm the source DB.
func executeReadOnlyQuery(ctx context.Context, db *sql.DB, driver, query string, rowLimit int, stmtTimeout time.Duration, workMem string) ([]string, [][]string, int64, error) {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	driver = normalizeExecDriver(driver)
	var rows *sql.Rows
	var err error
	switch driver {
	case "pgx":
		tx, terr := db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
		if terr != nil {
			return nil, nil, 0, terr
		}
		defer tx.Rollback()
		if stmtTimeout > 0 {
			_, _ = tx.ExecContext(ctx, fmt.Sprintf("SET LOCAL statement_timeout = %d", stmtTimeout.Milliseconds()))
		}
		if workMem != "" {
			_, _ = tx.ExecContext(ctx, "SET LOCAL work_mem = '"+strings.ReplaceAll(workMem, "'", "")+"'")
		}
		rows, err = tx.QueryContext(ctx, query)
	case "mysql":
		tx, terr := db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
		if terr != nil {
			return nil, nil, 0, terr
		}
		defer tx.Rollback()
		rows, err = tx.QueryContext(ctx, query)
	default:
		rows, err = db.QueryContext(ctx, query)
	}
	if err != nil {
		return nil, nil, 0, err
	}
	defer rows.Close()
	cols, err := rows.Columns()
	if err != nil {
		return nil, nil, 0, err
	}
	out := [][]string{}
	var count int64
	for rows.Next() {
		count++
		if len(out) >= rowLimit {
			continue // keep counting but stop materializing
		}
		cells := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range cells {
			ptrs[i] = &cells[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return nil, nil, 0, err
		}
		strRow := make([]string, len(cols))
		for i, c := range cells {
			strRow[i] = cellToString(c)
		}
		out = append(out, strRow)
	}
	return cols, out, count, rows.Err()
}

func cellToString(v any) string {
	switch t := v.(type) {
	case nil:
		return ""
	case []byte:
		return string(t)
	case string:
		return t
	default:
		return fmt.Sprintf("%v", t)
	}
}

// maskResultColumns masks the cells of every result column that a schema policy marks
// sensitivity=mask.
//
// Matching on the result column name alone is not enough. The result name is whatever the
// query called it, so "SELECT email AS customer_email" produces a column named
// customer_email and the mask misses — and an alias is not an attack, it is what
// generated SQL does by default, especially across a join. The protection would be
// present in the policy, reported in the audit footer, and absent from the output.
//
// So the SQL is consulted as well: an alias whose expression mentions a masked column is
// masked too. That errs towards masking, which is the right direction for a control whose
// purpose is to keep a value out of a result set.
func maskResultColumns(cols []string, rows [][]string, maskColumns []string, sqlText string) {
	if len(cols) == 0 || len(maskColumns) == 0 {
		return
	}
	byName := make(map[string]bool, len(maskColumns))
	for _, c := range maskColumns {
		if n := strings.ToLower(strings.TrimSpace(c)); n != "" {
			byName[n] = true
		}
	}
	aliased := aliasesOfMaskedColumns(sqlText, byName)

	mask := make([]bool, len(cols))
	for j, name := range cols {
		n := strings.ToLower(strings.TrimSpace(name))
		mask[j] = byName[n] || aliased[n]
	}
	for i := range rows {
		for j := range rows[i] {
			if j < len(mask) && mask[j] {
				rows[i][j] = maskText2SQLCell(rows[i][j])
			}
		}
	}
}

